import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z = vars
    return -(x + y + z)

def constraint1(vars):
    x, y, z = vars
    return (x + z)**2 * (x + y)**2 - 32 * x * y * z

# Let's try to maximize S = x + y + z subject to (x+z)^2(x+y)^2 = 32xyz.
# From (x+z)^2(x+y)^2 = 32xyz, we can see that if we scale x, y, z by k,
# the LHS scales by k^4 and the RHS by k^3.
# This means there's a specific scale for the solution.

def find_max_s():
    # Let's use the grid search to find a good starting point and then refine it.
    best_val = 0
    best_coords = None
    for x in np.linspace(0.1, 15, 100):
        for y in np.linspace(0.1, 15, 100):
            K = 32 * x / (x + y)**2
            disc = (2*x - K*y)**2 - 4*x**2
            if disc >= 0:
                z1 = (-(2*x - K*y) + np.sqrt(disc)) / 2
                z2 = (-(2*x - K*y) - np.sqrt(disc)) / 2
                for z in [z1, z2]:
                    if z > 0:
                        if x + y + z > best_val:
                            best_val = x + y + z
                            best_coords = (x, y, z)

    # Refine with minimize
    res = minimize(objective, best_coords, constraints={'type': 'eq', 'fun': constraint1},
                    bounds=[(1e-6, 100), (1e-6, 100), (1e-6, 100)])
    return -res.fun, res.x

print(find_max_s())

