import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z = vars
    return -(x + y + z)

def constraint1(vars):
    x, y, z = vars
    return (x + z)**2 * (x + y)**2 - 32 * x * y * z

# Let's try to find the maximum S more systematically.
# S = x+y+z. Let x, y, z be the variables.
# Let's use a more robust method to find the global maximum.
def find_max_s_robust():
    best_s = 0
    # Try various starting points
    for x0 in np.linspace(0.1, 10, 10):
        for y0 in np.linspace(0.1, 10, 10):
            for z0 in np.linspace(0.1, 10, 10):
                res = minimize(objective, [x0, y0, z0], 
                               constraints={'type': 'eq', 'fun': constraint1},
                               bounds=[(1e-6, 50), (1e-6, 50), (1e-6, 50)])
                if res.success:
                    best_s = max(best_s, -res.fun)
    return best_s

